import{_ as e}from"./chunks/create-reservation.Csqbo4RE.js";import{_ as r,o as t,c as o,a2 as l}from"./chunks/framework.CWgsre3x.js";const _=JSON.parse('{"title":"Δημιουργία κράτησης","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/create-reservation.md","filePath":"el/plus/create-reservation.md"}'),s={name:"el/plus/create-reservation.md"};function i(n,a,c,h,p,m){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="δημιουργια-κρατησης" tabindex="-1">Δημιουργία κράτησης <a class="header-anchor" href="#δημιουργια-κρατησης" aria-label="Permalink to &quot;Δημιουργία κράτησης&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Πηγαίος κώδικας TransferBook+ v0.7.9. Το παρόν είναι τοπικό προσχέδιο προς έλεγχο, όχι επιβεβαίωση διαθεσιμότητας στην παραγωγή. Ελέγξτε την εγκατεστημένη έκδοση και τα δικαιώματά σας.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/create-reservation.png"><img src="'+e+'" alt="Φόρμα απευθείας κράτησης: επιλέξτε υπηρεσία, διαδρομή, ημερομηνία, επιβάτες και κατηγορία οχήματος. Το όνομα και το τηλέφωνο είναι υποχρεωτικά· το email είναι προαιρετικό. Η εμφανιζόμενη τιμή είναι ενδεικτική."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Φόρμα απευθείας κράτησης: επιλέξτε υπηρεσία, διαδρομή, ημερομηνία, επιβάτες και κατηγορία οχήματος. Το όνομα και το τηλέφωνο είναι υποχρεωτικά· το email είναι προαιρετικό. Η εμφανιζόμενη τιμή είναι ενδεικτική.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή.</p><h2 id="πριν-ξεκινησετε" tabindex="-1">Πριν ξεκινήσετε <a class="header-anchor" href="#πριν-ξεκινησετε" aria-label="Permalink to &quot;Πριν ξεκινήσετε&quot;">​</a></h2><p>Απαιτείται εξουσιοδοτημένος χειριστής με δικαίωμα δημιουργίας κράτησης, ενεργή περιοχή και κατηγορία οχήματος.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Ανοίξτε τη φόρμα νέας κράτησης και επιλέξτε περιοχή και τύπο υπηρεσίας.</li><li>Επιλέξτε παραλαβή και προορισμό από τον κατάλογο. Για προσαρμοσμένη διεύθυνση επιβεβαιώστε με <strong>Use custom address</strong>. Στις συνήθεις μεταφορές η παραλαβή και ο προορισμός δεν μπορούν να είναι ίδια.</li><li>Καταχωρίστε ημερομηνία, ώρα, επιβάτες και αποσκευές. Επιλέξτε κατάλληλη κατηγορία οχήματος. Η ημερομηνία επιστροφής δεν μπορεί να προηγείται της αναχώρησης.</li><li>Συμπληρώστε <strong>Guest Full Name</strong> και <strong>Phone</strong>. Το <strong>Email (Optional)</strong> μπορεί να μείνει κενό. Προσθέστε στοιχεία πτήσης/πλοίου και πινακίδας, εφόσον χρειάζεται.</li><li>Ελέγξτε την προσφορά και τα πρόσθετα. Στην πιστοποιημένη λειτουργία περιμένετε την επαλήθευση της τρέχουσας τιμής από τον διακομιστή.</li><li>Υποβάλετε μία φορά και ελέγξτε τον κωδικό και την κατάσταση πριν από νέα αίτηση.</li></ol><h2 id="αναμενομενο-αποτελεσμα" tabindex="-1">Αναμενόμενο αποτέλεσμα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα&quot;">​</a></h2><p>Η φόρμα δημιουργεί αίτημα επιβεβαιωμένης κράτησης όταν επιτρέπεται από την τιμολόγηση ή νέας κράτησης σε αναμονή προσφοράς. Μη επαληθευμένη τιμή ή μη έγκυρη διαδρομή εμποδίζει την υποβολή.</p><h2 id="αντιμετωπιση-προβληματων" tabindex="-1">Αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Σε αβέβαιη απάντηση ελέγξτε τις κρατήσεις πριν από νέα προσπάθεια. Δείτε τις <a href="/el/plus/manual-quotations.html">χειροκίνητες προσφορές</a> και τα <a href="/el/plus/passenger-information.html">στοιχεία επιβάτη</a>.</p>',15)])])}const f=r(s,[["render",i]]);export{_ as __pageData,f as default};
